COMPLETE_DDL = '-- EcoBiome Scientific Foundation V1.1\n-- COMPLETE SQLITE RUNTIME DDL - OFF-REPO CANDIDATE V1.1\n-- DO NOT USE AS A CANONICAL DATABASE MIGRATION.\n--\n-- Authorized disposable runtime connection policy for the NEXT gate:\n--   sqlite3.connect(..., autocommit=True)\n--   PRAGMA foreign_keys=ON; verify 1\n--   PRAGMA journal_mode=DELETE; verify delete\n--   PRAGMA synchronous=FULL; verify 2\n--   connection.autocommit=False for UnitOfWork transactions\n--   WAL disabled by default in V1.1\n--\n\n-- PART A: PROVENANCE ENVELOPE\n\n-- EcoBiome Scientific Foundation V1.1\n-- SQLite provenance envelope - FROZEN V1.1 CANDIDATE DDL\n-- DO NOT EXECUTE.\n\nCREATE TABLE sf_schema_metadata (\n    schema_name TEXT PRIMARY KEY,\n    schema_version INTEGER NOT NULL CHECK (schema_version >= 1),\n    design_sha256 TEXT NOT NULL CHECK (length(design_sha256) = 64),\n    created_at TEXT NOT NULL,\n    CHECK (schema_name = \'scientific_foundation\')\n);\n\nCREATE TABLE knowledge_sources (\n    id TEXT PRIMARY KEY,\n    source_type TEXT NOT NULL,\n    canonical_locator TEXT NOT NULL,\n    title TEXT NOT NULL,\n    author TEXT,\n    language TEXT NOT NULL,\n    description TEXT NOT NULL DEFAULT \'\',\n    imported_at TEXT NOT NULL,\n    source_metadata_json TEXT NOT NULL DEFAULT \'{}\',\n    logical_identity_sha256 TEXT NOT NULL CHECK (length(logical_identity_sha256) = 64),\n    created_at TEXT NOT NULL\n);\n\nCREATE TABLE acquisition_jobs (\n    id TEXT PRIMARY KEY,\n    source_id TEXT,\n    adapter_name TEXT NOT NULL,\n    adapter_version TEXT NOT NULL,\n    requested_locator TEXT NOT NULL,\n    requested_language TEXT,\n    preferred_languages_json TEXT NOT NULL DEFAULT \'[]\',\n    maximum_input_bytes INTEGER,\n    outcome TEXT NOT NULL,\n    request_json TEXT NOT NULL DEFAULT \'{}\',\n    diagnostics_json TEXT NOT NULL DEFAULT \'[]\',\n    started_at TEXT,\n    completed_at TEXT,\n    created_at TEXT NOT NULL,\n    FOREIGN KEY (source_id) REFERENCES knowledge_sources(id)\n);\n\nCREATE TABLE retrievals (\n    id TEXT PRIMARY KEY,\n    acquisition_job_id TEXT NOT NULL,\n    retrieval_index INTEGER NOT NULL CHECK (retrieval_index >= 0),\n    retrieval_method TEXT NOT NULL,\n    requested_locator TEXT NOT NULL,\n    resolved_locator TEXT,\n    retrieved_at TEXT,\n    transport_status TEXT NOT NULL,\n    transport_metadata_json TEXT NOT NULL DEFAULT \'{}\',\n    created_at TEXT NOT NULL,\n    UNIQUE (acquisition_job_id, retrieval_index),\n    FOREIGN KEY (acquisition_job_id) REFERENCES acquisition_jobs(id)\n);\n\nCREATE TABLE raw_artifacts (\n    id TEXT PRIMARY KEY,\n    retrieval_id TEXT NOT NULL,\n    payload_role TEXT NOT NULL,\n    media_type TEXT NOT NULL,\n    size_bytes INTEGER NOT NULL CHECK (size_bytes >= 0),\n    content_sha256 TEXT NOT NULL CHECK (length(content_sha256) = 64),\n    artifact_store_key TEXT NOT NULL,\n    license_id TEXT,\n    license_evidence_locator TEXT,\n    materialization_policy TEXT NOT NULL,\n    immutable INTEGER NOT NULL DEFAULT 1 CHECK (immutable = 1),\n    created_at TEXT NOT NULL,\n    FOREIGN KEY (retrieval_id) REFERENCES retrievals(id)\n);\n\nCREATE TABLE representations (\n    id TEXT PRIMARY KEY,\n    source_id TEXT NOT NULL,\n    origin_raw_artifact_id TEXT,\n    logical_key TEXT NOT NULL,\n    representation_kind TEXT NOT NULL,\n    media_type TEXT NOT NULL,\n    language TEXT,\n    content_sha256 TEXT NOT NULL CHECK (length(content_sha256) = 64),\n    artifact_store_key TEXT,\n    materialization_status TEXT NOT NULL,\n    metadata_json TEXT NOT NULL DEFAULT \'{}\',\n    created_at TEXT NOT NULL,\n    FOREIGN KEY (source_id) REFERENCES knowledge_sources(id),\n    FOREIGN KEY (origin_raw_artifact_id) REFERENCES raw_artifacts(id)\n);\n\nCREATE TABLE derivations (\n    id TEXT PRIMARY KEY,\n    child_representation_id TEXT NOT NULL,\n    parent_raw_artifact_id TEXT,\n    parent_representation_id TEXT,\n    derivation_method TEXT NOT NULL,\n    tool_name TEXT,\n    tool_version TEXT,\n    parameters_json TEXT NOT NULL DEFAULT \'{}\',\n    created_at TEXT NOT NULL,\n    CHECK (\n        (parent_raw_artifact_id IS NOT NULL AND parent_representation_id IS NULL)\n        OR\n        (parent_raw_artifact_id IS NULL AND parent_representation_id IS NOT NULL)\n    ),\n    FOREIGN KEY (child_representation_id) REFERENCES representations(id),\n    FOREIGN KEY (parent_raw_artifact_id) REFERENCES raw_artifacts(id),\n    FOREIGN KEY (parent_representation_id) REFERENCES representations(id)\n);\n\nCREATE TABLE segments (\n    id TEXT PRIMARY KEY,\n    representation_id TEXT NOT NULL,\n    segment_index INTEGER NOT NULL CHECK (segment_index >= 0),\n    text_inline TEXT,\n    text_sha256 TEXT NOT NULL CHECK (length(text_sha256) = 64),\n    materialization_status TEXT NOT NULL,\n    representation_char_start INTEGER,\n    representation_char_end INTEGER,\n    start_seconds_decimal TEXT,\n    end_seconds_decimal TEXT,\n    page_number INTEGER,\n    frame_start INTEGER,\n    frame_end INTEGER,\n    review_status TEXT,\n    metadata_json TEXT NOT NULL DEFAULT \'{}\',\n    created_at TEXT NOT NULL,\n    UNIQUE (representation_id, segment_index),\n    CHECK (\n        representation_char_start IS NULL\n        OR representation_char_end IS NULL\n        OR representation_char_end >= representation_char_start\n    ),\n    FOREIGN KEY (representation_id) REFERENCES representations(id)\n);\n\nCREATE TABLE source_evidence (\n    id TEXT PRIMARY KEY,\n    segment_id TEXT NOT NULL,\n    segment_char_start INTEGER NOT NULL CHECK (segment_char_start >= 0),\n    segment_char_end INTEGER NOT NULL CHECK (segment_char_end > segment_char_start),\n    evidence_text_sha256 TEXT NOT NULL CHECK (length(evidence_text_sha256) = 64),\n    start_seconds_decimal TEXT,\n    end_seconds_decimal TEXT,\n    page_number INTEGER,\n    frame_start INTEGER,\n    frame_end INTEGER,\n    evidence_metadata_json TEXT NOT NULL DEFAULT \'{}\',\n    created_at TEXT NOT NULL,\n    UNIQUE (segment_id, segment_char_start, segment_char_end, evidence_text_sha256),\n    FOREIGN KEY (segment_id) REFERENCES segments(id)\n);\n\nCREATE TABLE source_claims (\n    id TEXT PRIMARY KEY,\n    source_id TEXT NOT NULL,\n    representation_id TEXT,\n    parent_claim_id TEXT,\n    claim_layer TEXT NOT NULL CHECK (claim_layer IN (\'extracted\', \'atomic\')),\n    claim_text TEXT NOT NULL,\n    claim_text_sha256 TEXT NOT NULL CHECK (length(claim_text_sha256) = 64),\n    claim_kind TEXT,\n    semantic_type TEXT,\n    qualifiers_json TEXT NOT NULL DEFAULT \'{}\',\n    extraction_confidence_decimal TEXT,\n    source_claim_effective_text_sha256 TEXT,\n    notes TEXT NOT NULL DEFAULT \'\',\n    initial_review_status TEXT,\n    created_at TEXT NOT NULL,\n    FOREIGN KEY (source_id) REFERENCES knowledge_sources(id),\n    FOREIGN KEY (representation_id) REFERENCES representations(id),\n    FOREIGN KEY (parent_claim_id) REFERENCES source_claims(id)\n);\n\nCREATE TABLE claim_evidence_links (\n    claim_id TEXT NOT NULL,\n    evidence_id TEXT NOT NULL,\n    evidence_order INTEGER NOT NULL DEFAULT 0 CHECK (evidence_order >= 0),\n    link_role TEXT NOT NULL DEFAULT \'supports_source_claim\',\n    created_at TEXT NOT NULL,\n    PRIMARY KEY (claim_id, evidence_id),\n    FOREIGN KEY (claim_id) REFERENCES source_claims(id),\n    FOREIGN KEY (evidence_id) REFERENCES source_evidence(id)\n);\n\nCREATE TABLE claim_review_events (\n    id TEXT PRIMARY KEY,\n    claim_id TEXT NOT NULL,\n    decision TEXT NOT NULL CHECK (decision IN (\'accept\',\'correct\',\'reject\')),\n    reviewer TEXT,\n    notes TEXT NOT NULL DEFAULT \'\',\n    corrected_text TEXT,\n    corrected_text_sha256 TEXT,\n    review_metadata_json TEXT NOT NULL DEFAULT \'{}\',\n    reviewed_at TEXT NOT NULL,\n    CHECK (\n        decision <> \'correct\'\n        OR (\n            corrected_text IS NOT NULL\n            AND length(trim(corrected_text)) > 0\n        )\n    ),\n    CHECK (\n        (corrected_text IS NULL AND corrected_text_sha256 IS NULL)\n        OR\n        (corrected_text IS NOT NULL AND corrected_text_sha256 IS NOT NULL)\n    ),\n    FOREIGN KEY (claim_id) REFERENCES source_claims(id)\n);\n\nCREATE TABLE segment_review_events (\n    id TEXT PRIMARY KEY,\n    segment_id TEXT NOT NULL REFERENCES segments(id) ON DELETE RESTRICT,\n    decision TEXT NOT NULL CHECK (decision IN (\'accept\',\'correct\',\'reject\')),\n    reviewer TEXT,\n    rationale TEXT NOT NULL DEFAULT \'\',\n    corrected_text TEXT,\n    corrected_text_sha256 TEXT,\n    review_metadata_json TEXT NOT NULL DEFAULT \'{}\',\n    reviewed_at TEXT NOT NULL,\n    CHECK (\n        decision <> \'correct\'\n        OR (\n            corrected_text IS NOT NULL\n            AND length(trim(corrected_text)) > 0\n        )\n    ),\n    CHECK (\n        (corrected_text IS NULL AND corrected_text_sha256 IS NULL)\n        OR\n        (corrected_text IS NOT NULL AND corrected_text_sha256 IS NOT NULL)\n    )\n);\n\nCREATE INDEX idx_acquisition_jobs_source ON acquisition_jobs(source_id);\nCREATE INDEX idx_retrievals_job ON retrievals(acquisition_job_id);\nCREATE INDEX idx_raw_artifacts_retrieval ON raw_artifacts(retrieval_id);\nCREATE INDEX idx_raw_artifacts_sha256 ON raw_artifacts(content_sha256);\nCREATE INDEX idx_representations_source ON representations(source_id);\nCREATE INDEX idx_representations_raw_artifact ON representations(origin_raw_artifact_id);\nCREATE INDEX idx_representations_sha256 ON representations(content_sha256);\nCREATE INDEX idx_derivations_child ON derivations(child_representation_id);\nCREATE INDEX idx_derivations_parent_representation ON derivations(parent_representation_id);\nCREATE INDEX idx_segments_representation ON segments(representation_id, segment_index);\nCREATE INDEX idx_source_evidence_segment ON source_evidence(segment_id);\nCREATE INDEX idx_source_claims_source ON source_claims(source_id);\nCREATE INDEX idx_source_claims_representation ON source_claims(representation_id);\nCREATE INDEX idx_source_claims_parent ON source_claims(parent_claim_id);\nCREATE INDEX idx_source_claims_text_sha ON source_claims(claim_text_sha256);\nCREATE INDEX idx_claim_evidence_evidence ON claim_evidence_links(evidence_id);\nCREATE INDEX idx_claim_reviews_claim_time ON claim_review_events(claim_id, reviewed_at);\nCREATE INDEX segment_review_events_segment_time_idx\nON segment_review_events(segment_id, reviewed_at, id);\n\n-- PART B: SCIENTIFIC FOUNDATION CORE\n\n-- EcoBiome Scientific Foundation V1.1\n-- CONSOLIDATED LOGICAL DDL — FROZEN V1.1 CANDIDATE DDL\n-- DO NOT EXECUTE AS A MIGRATION.\n--\n-- This artifact combines the frozen 5-table Scientific Entity Identity\n-- addendum with the frozen 7-table cumulative knowledge/evidence core.\n--\n-- Before any migration:\n-- 1. reconcile exact foreign keys with current Collector schema;\n-- 2. create restorable database backup;\n-- 3. prove forward migration on a copy;\n-- 4. prove rollback/restoration;\n-- 5. run full regression tests;\n-- 6. preserve all source/claim provenance and review invariants.\n--\n\n-- ============================================================\n-- PART A — GENERIC SCIENTIFIC ENTITY IDENTITY LAYER\n-- ============================================================\n\n-- EcoBiome Scientific Foundation V1.1\n-- Scientific Entity Identity Layer — LOGICAL DDL ADDENDUM\n-- FROZEN V1.1 CANDIDATE DDL. NOT A CANONICAL MIGRATION.\n\nCREATE TABLE scientific_entities (\n    id TEXT PRIMARY KEY,\n    entity_kind TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    retired_at TEXT\n);\n\nCREATE TABLE scientific_entity_revisions (\n    entity_id TEXT NOT NULL,\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    schema_version TEXT NOT NULL,\n    canonical_label TEXT NOT NULL,\n    canonical_payload_json TEXT NOT NULL DEFAULT \'{}\',\n    canonical_payload_sha256 TEXT NOT NULL,\n    review_status TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    PRIMARY KEY (entity_id, revision),\n    UNIQUE (schema_version, canonical_payload_sha256),\n    FOREIGN KEY (entity_id)\n        REFERENCES scientific_entities(id)\n);\n\nCREATE TABLE scientific_entity_identifiers (\n    id TEXT PRIMARY KEY,\n    entity_id TEXT NOT NULL,\n    scheme TEXT NOT NULL,\n    authority_namespace TEXT NOT NULL,\n    authority_version TEXT NOT NULL DEFAULT \'\',\n    external_id TEXT NOT NULL,\n    mapping_status TEXT NOT NULL CHECK (\n        mapping_status IN (\n            \'exact\',\n            \'synonym\',\n            \'historic\',\n            \'deprecated\',\n            \'conflicted\',\n            \'unresolved\'\n        )\n    ),\n    mapping_review_status TEXT NOT NULL CHECK (\n        mapping_review_status IN (\n            \'unreviewed\',\n            \'reviewed_confirmed\',\n            \'reviewed_rejected\'\n        )\n    ),\n    authority_source_id TEXT,\n    valid_from TEXT,\n    valid_to TEXT,\n    created_at TEXT NOT NULL,\n    FOREIGN KEY (entity_id)\n        REFERENCES scientific_entities(id),\n    FOREIGN KEY (authority_source_id)\n        REFERENCES knowledge_sources(id)\n);\n\nCREATE TABLE scientific_entity_name_usages (\n    id TEXT PRIMARY KEY,\n    entity_id TEXT,\n    source_id TEXT NOT NULL,\n    verbatim_name TEXT NOT NULL,\n    language TEXT,\n    script TEXT,\n    usage_status TEXT NOT NULL,\n    nomenclatural_status TEXT,\n    mapping_review_status TEXT NOT NULL CHECK (\n        mapping_review_status IN (\n            \'unreviewed\',\n            \'reviewed_confirmed\',\n            \'reviewed_rejected\'\n        )\n    ),\n    source_version TEXT,\n    retrieval_id TEXT,\n    segment_id TEXT,\n    segment_char_start INTEGER,\n    segment_char_end INTEGER,\n    created_at TEXT NOT NULL,\n    CHECK (\n        (segment_char_start IS NULL AND segment_char_end IS NULL)\n        OR (\n            segment_id IS NOT NULL\n            AND segment_char_start IS NOT NULL\n            AND segment_char_end IS NOT NULL\n            AND segment_char_start >= 0\n            AND segment_char_end > segment_char_start\n        )\n    ),\n    FOREIGN KEY (entity_id)\n        REFERENCES scientific_entities(id),\n    FOREIGN KEY (source_id)\n        REFERENCES knowledge_sources(id),\n    FOREIGN KEY (retrieval_id)\n        REFERENCES retrievals(id),\n    FOREIGN KEY (segment_id)\n        REFERENCES segments(id)\n);\n\nCREATE TABLE scientific_entity_relations (\n    id TEXT PRIMARY KEY,\n    subject_entity_id TEXT NOT NULL,\n    relation TEXT NOT NULL CHECK (\n        relation IN (\n            \'same_biological_material_as\',\n            \'part_of\',\n            \'strain_of\',\n            \'population_of\',\n            \'cultivar_of\',\n            \'ecotype_of\',\n            \'deposit_of\',\n            \'contains\'\n        )\n    ),\n    object_entity_id TEXT NOT NULL,\n    semantics_version TEXT NOT NULL,\n    qualifiers_json TEXT NOT NULL DEFAULT \'{}\',\n    review_status TEXT NOT NULL,\n    valid_from TEXT,\n    valid_to TEXT,\n    created_at TEXT NOT NULL,\n    CHECK (subject_entity_id <> object_entity_id),\n    CHECK (\n        relation <> \'same_biological_material_as\'\n        OR subject_entity_id < object_entity_id\n    ),\n    FOREIGN KEY (subject_entity_id)\n        REFERENCES scientific_entities(id),\n    FOREIGN KEY (object_entity_id)\n        REFERENCES scientific_entities(id)\n);\n\n-- The existing ScientificAssertion canonical serializer must be amended so\n-- entity-valued subject/object/qualifiers reference:\n--\n--   {"entity_id": "...", "entity_revision": N}\n--\n-- rather than using canonical-name strings as identity.\n--\n-- This addendum remains lineage-neutral. No fish/plant/bacterium core tables.\n\n-- ============================================================\n-- PART B — CUMULATIVE KNOWLEDGE / EVIDENCE CORE\n-- ============================================================\n\n-- EcoBiome Scientific Foundation V1.1 — LOGICAL DDL DRAFT\n-- FROZEN V1.1 CANDIDATE DDL. NOT A CANONICAL MIGRATION.\n-- Foreign keys target the durable provenance-envelope tables frozen in this schema.\n-- This is a fresh V1.1 disposable schema identity, not an in-place migration.\n\nCREATE TABLE scientific_assertions (\n    id TEXT PRIMARY KEY,\n    created_at TEXT NOT NULL,\n    retired_at TEXT\n);\n\nCREATE TABLE scientific_assertion_revisions (\n    assertion_id TEXT NOT NULL,\n    revision INTEGER NOT NULL CHECK (revision >= 1),\n    schema_version TEXT NOT NULL,\n    assertion_kind TEXT NOT NULL CHECK (\n        assertion_kind IN (\n            \'relational\',\n            \'measurement\',\n            \'event\',\n            \'process\',\n            \'classification\',\n            \'temporal_pattern\'\n        )\n    ),\n    predicate TEXT NOT NULL,\n    participants_json TEXT NOT NULL,\n    value_json TEXT NOT NULL,\n    qualifiers_json TEXT NOT NULL DEFAULT \'{}\',\n    normalized_text TEXT NOT NULL,\n    canonical_payload_sha256 TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    PRIMARY KEY (assertion_id, revision),\n    UNIQUE (schema_version, canonical_payload_sha256),\n    FOREIGN KEY (assertion_id)\n        REFERENCES scientific_assertions(id)\n);\n\nCREATE TABLE assertion_claim_links (\n    id TEXT PRIMARY KEY,\n    assertion_id TEXT NOT NULL,\n    assertion_revision INTEGER NOT NULL,\n    claim_id TEXT NOT NULL,\n    stance TEXT NOT NULL CHECK (\n        stance IN (\n            \'supports\',\n            \'contradicts\',\n            \'qualifies\',\n            \'context_only\',\n            \'duplicate_report\'\n        )\n    ),\n    support_mode TEXT NOT NULL,\n    scope_alignment TEXT NOT NULL,\n    semantic_alignment TEXT NOT NULL,\n    review_status TEXT NOT NULL,\n    reviewed_by TEXT,\n    reviewed_at TEXT,\n    created_at TEXT NOT NULL,\n    UNIQUE (assertion_id, assertion_revision, claim_id),\n    FOREIGN KEY (assertion_id, assertion_revision)\n        REFERENCES scientific_assertion_revisions(assertion_id, revision),\n    FOREIGN KEY (claim_id)\n        REFERENCES source_claims(id)\n);\n\nCREATE TABLE source_assessments (\n    id TEXT PRIMARY KEY,\n    source_id TEXT NOT NULL,\n    policy_version TEXT NOT NULL,\n    source_class TEXT NOT NULL,\n    peer_review_status TEXT NOT NULL,\n    publication_status TEXT NOT NULL,\n    retraction_status TEXT NOT NULL,\n    license_status TEXT NOT NULL,\n    institutional_or_publisher_context_json TEXT NOT NULL DEFAULT \'{}\',\n    assessment_notes_json TEXT NOT NULL DEFAULT \'{}\',\n    assessor TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    supersedes_assessment_id TEXT,\n    FOREIGN KEY (source_id)\n        REFERENCES knowledge_sources(id),\n    FOREIGN KEY (supersedes_assessment_id)\n        REFERENCES source_assessments(id)\n);\n\nCREATE TABLE evidence_assessments (\n    id TEXT PRIMARY KEY,\n    assertion_claim_link_id TEXT NOT NULL,\n    policy_version TEXT NOT NULL,\n    study_design TEXT NOT NULL,\n    evidence_directness TEXT NOT NULL,\n    endpoint_or_response_json TEXT NOT NULL DEFAULT \'{}\',\n    study_scope_json TEXT NOT NULL DEFAULT \'{}\',\n    methodological_dimensions_json TEXT NOT NULL DEFAULT \'{}\',\n    statistical_result_json TEXT NOT NULL DEFAULT \'{}\',\n    independence_status TEXT NOT NULL,\n    limitations_json TEXT NOT NULL DEFAULT \'{}\',\n    assessor TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    supersedes_assessment_id TEXT,\n    FOREIGN KEY (assertion_claim_link_id)\n        REFERENCES assertion_claim_links(id),\n    FOREIGN KEY (supersedes_assessment_id)\n        REFERENCES evidence_assessments(id)\n);\n\nCREATE TABLE source_lineage_edges (\n    id TEXT PRIMARY KEY,\n    parent_source_id TEXT NOT NULL,\n    child_source_id TEXT NOT NULL,\n    relation TEXT NOT NULL,\n    basis_claim_id TEXT,\n    basis_evidence_json TEXT NOT NULL DEFAULT \'{}\',\n    review_status TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    CHECK (parent_source_id <> child_source_id),\n    FOREIGN KEY (parent_source_id)\n        REFERENCES knowledge_sources(id),\n    FOREIGN KEY (child_source_id)\n        REFERENCES knowledge_sources(id),\n    FOREIGN KEY (basis_claim_id)\n        REFERENCES source_claims(id)\n);\n\nCREATE TABLE knowledge_syntheses (\n    id TEXT PRIMARY KEY,\n    assertion_id TEXT NOT NULL,\n    assertion_revision INTEGER NOT NULL,\n    synthesis_revision INTEGER NOT NULL CHECK (synthesis_revision >= 1),\n    policy_version TEXT NOT NULL,\n    evidence_state TEXT NOT NULL CHECK (\n        evidence_state IN (\n            \'insufficient\',\n            \'single_source_supported\',\n            \'multi_source_supported\',\n            \'contested\',\n            \'contradicted_by_stronger_evidence\',\n            \'superseded\'\n        )\n    ),\n    support_link_count INTEGER NOT NULL CHECK (support_link_count >= 0),\n    contradict_link_count INTEGER NOT NULL CHECK (contradict_link_count >= 0),\n    independent_support_origin_count INTEGER NOT NULL\n        CHECK (independent_support_origin_count >= 0),\n    independent_contradict_origin_count INTEGER NOT NULL\n        CHECK (independent_contradict_origin_count >= 0),\n    source_class_distribution_json TEXT NOT NULL DEFAULT \'{}\',\n    methodological_diversity_json TEXT NOT NULL DEFAULT \'{}\',\n    scope_summary_json TEXT NOT NULL DEFAULT \'{}\',\n    uncertainties_json TEXT NOT NULL DEFAULT \'{}\',\n    conflicts_json TEXT NOT NULL DEFAULT \'{}\',\n    review_status TEXT NOT NULL,\n    reviewed_by TEXT,\n    created_at TEXT NOT NULL,\n    UNIQUE (assertion_id, assertion_revision, synthesis_revision),\n    FOREIGN KEY (assertion_id, assertion_revision)\n        REFERENCES scientific_assertion_revisions(assertion_id, revision)\n);\n\n-- Explicitly absent:\n--   truth_probability REAL\n--   confidence REAL\n--   is_scientifically_true BOOLEAN\n--   auto_accept BOOLEAN\n\n-- ============================================================\n-- CONSOLIDATION AMENDMENT\n-- ============================================================\n-- scientific_assertion_revisions.participants_json/value_json/\n-- qualifiers_json are canonical V1.1 proposition storage.\n-- Entity-valued participants/values MUST serialize typed entity refs:\n--   {"type":"entity_ref","entity_id":"...","entity_revision":N}\n-- Scientific numeric values MUST use explicit typed decimal objects.\n-- Display-name strings MUST NOT act as entity identity.\n--\n-- No truth_probability/confidence/is_scientifically_true/auto_accept.\n\n-- ============================================================\n-- PART C — SEMANTIC PROVIDER AUDIT + CANONICAL CANDIDATES V5\n-- ============================================================\n-- Schema V5 remains fresh-database only.\n-- Provider provenance is auditability only and never scientific weight.\n-- Canonical semantic candidates and human review history are immutable /\n-- append-only. No automatic scientific acceptance is permitted.\n\nCREATE TABLE semantic_provider_runs (\n    id TEXT PRIMARY KEY,\n    run_kind TEXT NOT NULL CHECK (run_kind = \'semantic_extraction\'),\n    provider_name TEXT NOT NULL,\n    provider_adapter_name TEXT NOT NULL,\n    provider_adapter_version TEXT NOT NULL,\n    endpoint TEXT,\n    model_requested TEXT NOT NULL,\n    semantic_contract_name TEXT NOT NULL,\n    semantic_contract_version TEXT NOT NULL,\n    semantic_contract_sha256 TEXT NOT NULL\n        CHECK (length(semantic_contract_sha256) = 64),\n    instruction_sha256 TEXT NOT NULL\n        CHECK (length(instruction_sha256) = 64),\n    output_schema_sha256 TEXT NOT NULL\n        CHECK (length(output_schema_sha256) = 64),\n    source_request_sha256 TEXT NOT NULL\n        CHECK (length(source_request_sha256) = 64),\n    request_body_sha256 TEXT NOT NULL\n        CHECK (length(request_body_sha256) = 64),\n    request_artifact_store_key TEXT NOT NULL,\n    request_fingerprint_sha256 TEXT NOT NULL\n        CHECK (length(request_fingerprint_sha256) = 64),\n    safe_configuration_json TEXT NOT NULL DEFAULT \'{}\',\n    started_at TEXT,\n    created_at TEXT NOT NULL\n);\n\nCREATE TABLE semantic_provider_run_claim_inputs (\n    run_id TEXT NOT NULL,\n    claim_id TEXT NOT NULL,\n    input_order INTEGER NOT NULL CHECK (input_order >= 0),\n    claim_effective_text_sha256 TEXT NOT NULL\n        CHECK (length(claim_effective_text_sha256) = 64),\n    claim_review_status_at_run TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    PRIMARY KEY (run_id, claim_id),\n    UNIQUE (run_id, input_order),\n    FOREIGN KEY (run_id)\n        REFERENCES semantic_provider_runs(id),\n    FOREIGN KEY (claim_id)\n        REFERENCES source_claims(id)\n);\n\nCREATE TABLE semantic_provider_run_evidence_inputs (\n    run_id TEXT NOT NULL,\n    claim_id TEXT NOT NULL,\n    evidence_id TEXT NOT NULL,\n    evidence_order INTEGER NOT NULL CHECK (evidence_order >= 0),\n    evidence_text_sha256 TEXT NOT NULL\n        CHECK (length(evidence_text_sha256) = 64),\n    segment_review_status_at_run TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    PRIMARY KEY (run_id, evidence_id),\n    UNIQUE (run_id, claim_id, evidence_order),\n    FOREIGN KEY (run_id, claim_id)\n        REFERENCES semantic_provider_run_claim_inputs(run_id, claim_id),\n    FOREIGN KEY (claim_id, evidence_id)\n        REFERENCES claim_evidence_links(claim_id, evidence_id)\n);\n\nCREATE TABLE semantic_provider_run_events (\n    id TEXT PRIMARY KEY,\n    run_id TEXT NOT NULL,\n    event_index INTEGER NOT NULL CHECK (event_index >= 0),\n    event_type TEXT NOT NULL CHECK (\n        event_type IN (\n            \'provider_response_received\',\n            \'provider_refusal\',\n            \'transport_failed\',\n            \'provider_failed\',\n            \'output_validation_failed\',\n            \'validated\',\n            \'completed\',\n            \'cancelled\'\n        )\n    ),\n    model_returned TEXT,\n    provider_request_id TEXT,\n    provider_response_id TEXT,\n    http_status_code INTEGER,\n    response_status TEXT,\n    content_type TEXT,\n    response_body_sha256 TEXT,\n    response_artifact_store_key TEXT,\n    validated_output_sha256 TEXT,\n    validated_output_artifact_store_key TEXT,\n    usage_json TEXT NOT NULL DEFAULT \'{}\',\n    diagnostics_json TEXT NOT NULL DEFAULT \'{}\',\n    proposal_count INTEGER CHECK (\n        proposal_count IS NULL OR proposal_count >= 0\n    ),\n    created_at TEXT NOT NULL,\n    UNIQUE (run_id, event_index),\n    CHECK (\n        (response_body_sha256 IS NULL\n            AND response_artifact_store_key IS NULL)\n        OR\n        (response_body_sha256 IS NOT NULL\n            AND length(response_body_sha256) = 64\n            AND response_artifact_store_key IS NOT NULL)\n    ),\n    CHECK (\n        (validated_output_sha256 IS NULL\n            AND validated_output_artifact_store_key IS NULL)\n        OR\n        (validated_output_sha256 IS NOT NULL\n            AND length(validated_output_sha256) = 64\n            AND validated_output_artifact_store_key IS NOT NULL)\n    ),\n    FOREIGN KEY (run_id)\n        REFERENCES semantic_provider_runs(id)\n);\n\nCREATE TABLE semantic_candidates (\n    id TEXT PRIMARY KEY,\n    schema_version TEXT NOT NULL,\n    semantic_contract_name TEXT NOT NULL,\n    semantic_contract_version TEXT NOT NULL,\n    semantic_contract_sha256 TEXT NOT NULL\n        CHECK (length(semantic_contract_sha256) = 64),\n    relation_type_basis_version TEXT NOT NULL,\n    relation_type_registry_sha256 TEXT NOT NULL\n        CHECK (length(relation_type_registry_sha256) = 64),\n    grounding_policy_sha256 TEXT NOT NULL\n        CHECK (length(grounding_policy_sha256) = 64),\n    claim_scoped_provenance_policy_sha256 TEXT NOT NULL\n        CHECK (length(claim_scoped_provenance_policy_sha256) = 64),\n    source_statement_claim_id TEXT NOT NULL,\n    source_claim_effective_text_sha256 TEXT NOT NULL\n        CHECK (length(source_claim_effective_text_sha256) = 64),\n    semantic_type TEXT NOT NULL,\n    relation TEXT NOT NULL,\n    epistemic_class TEXT NOT NULL,\n    promotion_readiness TEXT NOT NULL CHECK (\n        promotion_readiness IN (\n            \'grounding_complete\',\n            \'requires_semantic_resolution\'\n        )\n    ),\n    automatic_scientific_acceptance INTEGER NOT NULL DEFAULT 0\n        CHECK (automatic_scientific_acceptance = 0),\n    canonical_candidate_sha256 TEXT NOT NULL\n        CHECK (length(canonical_candidate_sha256) = 64),\n    canonical_candidate_document_sha256 TEXT NOT NULL\n        CHECK (length(canonical_candidate_document_sha256) = 64),\n    canonical_candidate_json TEXT NOT NULL,\n    created_at TEXT NOT NULL,\n    UNIQUE (canonical_candidate_sha256),\n    UNIQUE (id, source_statement_claim_id),\n    UNIQUE (id, canonical_candidate_sha256),\n    FOREIGN KEY (source_statement_claim_id)\n        REFERENCES source_claims(id)\n);\n\nCREATE TABLE semantic_candidate_evidence_links (\n    semantic_candidate_id TEXT NOT NULL,\n    source_statement_claim_id TEXT NOT NULL,\n    evidence_id TEXT NOT NULL,\n    evidence_order INTEGER NOT NULL CHECK (evidence_order >= 0),\n    created_at TEXT NOT NULL,\n    PRIMARY KEY (semantic_candidate_id, evidence_id),\n    UNIQUE (semantic_candidate_id, evidence_order),\n    FOREIGN KEY (semantic_candidate_id, source_statement_claim_id)\n        REFERENCES semantic_candidates(id, source_statement_claim_id),\n    FOREIGN KEY (source_statement_claim_id, evidence_id)\n        REFERENCES claim_evidence_links(claim_id, evidence_id)\n);\n\nCREATE TABLE semantic_candidate_review_events (\n    id TEXT PRIMARY KEY,\n    semantic_candidate_id TEXT NOT NULL,\n    semantic_candidate_sha256 TEXT NOT NULL\n        CHECK (length(semantic_candidate_sha256) = 64),\n    decision TEXT NOT NULL CHECK (\n        decision IN (\'accept\', \'correct\', \'reject\')\n    ),\n    reviewer TEXT NOT NULL CHECK (length(trim(reviewer)) > 0),\n    review_text TEXT NOT NULL CHECK (length(trim(review_text)) > 0),\n    review_text_sha256 TEXT NOT NULL\n        CHECK (length(review_text_sha256) = 64),\n    rationale TEXT NOT NULL DEFAULT \'\',\n    review_metadata_json TEXT NOT NULL DEFAULT \'{}\',\n    review_policy_name TEXT NOT NULL,\n    review_policy_version TEXT NOT NULL,\n    review_policy_sha256 TEXT NOT NULL\n        CHECK (length(review_policy_sha256) = 64),\n    replacement_candidate_id TEXT,\n    replacement_candidate_sha256 TEXT,\n    reviewed_at TEXT NOT NULL,\n    CHECK (\n        (replacement_candidate_id IS NULL\n            AND replacement_candidate_sha256 IS NULL)\n        OR\n        (replacement_candidate_id IS NOT NULL\n            AND replacement_candidate_sha256 IS NOT NULL\n            AND length(replacement_candidate_sha256) = 64)\n    ),\n    CHECK (\n        (decision = \'correct\'\n            AND replacement_candidate_id IS NOT NULL)\n        OR\n        (decision IN (\'accept\', \'reject\')\n            AND replacement_candidate_id IS NULL)\n    ),\n    CHECK (\n        replacement_candidate_id IS NULL\n        OR replacement_candidate_id <> semantic_candidate_id\n    ),\n    FOREIGN KEY (semantic_candidate_id, semantic_candidate_sha256)\n        REFERENCES semantic_candidates(id, canonical_candidate_sha256),\n    FOREIGN KEY (replacement_candidate_id, replacement_candidate_sha256)\n        REFERENCES semantic_candidates(id, canonical_candidate_sha256)\n);\n\nCREATE TABLE semantic_provider_candidate_origins (\n    run_id TEXT NOT NULL,\n    proposal_index INTEGER NOT NULL CHECK (proposal_index >= 0),\n    semantic_candidate_id TEXT NOT NULL,\n    proposal_sha256 TEXT NOT NULL CHECK (length(proposal_sha256) = 64),\n    created_at TEXT NOT NULL,\n    PRIMARY KEY (run_id, proposal_index),\n    FOREIGN KEY (run_id)\n        REFERENCES semantic_provider_runs(id),\n    FOREIGN KEY (semantic_candidate_id)\n        REFERENCES semantic_candidates(id)\n);\n'
INDEX_ADDENDUM = "-- EcoBiome Scientific Foundation V1.1\n-- SQLite physical-index addendum - FROZEN V1.1 CANDIDATE.\n\nCREATE INDEX idx_entity_identifiers_entity\n    ON scientific_entity_identifiers(entity_id);\n\nCREATE INDEX idx_entity_identifiers_authority_external\n    ON scientific_entity_identifiers(\n        scheme,\n        authority_namespace,\n        authority_version,\n        external_id\n    );\n\nCREATE INDEX idx_entity_name_usages_entity\n    ON scientific_entity_name_usages(entity_id);\n\nCREATE INDEX idx_entity_name_usages_source\n    ON scientific_entity_name_usages(source_id);\n\nCREATE INDEX idx_entity_name_usages_retrieval\n    ON scientific_entity_name_usages(retrieval_id);\n\nCREATE INDEX idx_entity_name_usages_segment\n    ON scientific_entity_name_usages(segment_id);\n\nCREATE INDEX idx_entity_relations_subject\n    ON scientific_entity_relations(subject_entity_id);\n\nCREATE INDEX idx_entity_relations_object\n    ON scientific_entity_relations(object_entity_id);\n\nCREATE INDEX idx_assertion_claim_links_claim\n    ON assertion_claim_links(claim_id);\n\nCREATE INDEX idx_source_assessments_source\n    ON source_assessments(source_id);\n\nCREATE INDEX idx_evidence_assessments_link\n    ON evidence_assessments(assertion_claim_link_id);\n\nCREATE INDEX idx_source_lineage_parent\n    ON source_lineage_edges(parent_source_id);\n\nCREATE INDEX idx_source_lineage_child\n    ON source_lineage_edges(child_source_id);\n\nCREATE INDEX idx_source_lineage_basis_claim\n    ON source_lineage_edges(basis_claim_id);\n\n-- ============================================================\n-- Schema V5 semantic-provider / candidate explicit indexes\n-- ============================================================\n\nCREATE INDEX semantic_provider_runs_request_fingerprint_idx\n    ON semantic_provider_runs(request_fingerprint_sha256);\n\nCREATE INDEX semantic_provider_run_claim_inputs_claim_idx\n    ON semantic_provider_run_claim_inputs(claim_id);\n\nCREATE INDEX semantic_provider_run_evidence_inputs_claim_evidence_idx\n    ON semantic_provider_run_evidence_inputs(claim_id, evidence_id);\n\nCREATE UNIQUE INDEX semantic_provider_run_events_one_validated_idx\n    ON semantic_provider_run_events(run_id)\n    WHERE event_type = 'validated';\n\nCREATE UNIQUE INDEX semantic_provider_run_events_one_terminal_idx\n    ON semantic_provider_run_events(run_id)\n    WHERE event_type IN (\n        'provider_refusal',\n        'transport_failed',\n        'provider_failed',\n        'output_validation_failed',\n        'completed',\n        'cancelled'\n    );\n\nCREATE INDEX semantic_provider_candidate_origins_candidate_idx\n    ON semantic_provider_candidate_origins(semantic_candidate_id);\n\nCREATE INDEX semantic_candidates_source_statement_claim_idx\n    ON semantic_candidates(source_statement_claim_id);\n\nCREATE INDEX semantic_candidates_relation_type_idx\n    ON semantic_candidates(relation, semantic_type);\n\nCREATE INDEX semantic_candidate_evidence_links_claim_evidence_idx\n    ON semantic_candidate_evidence_links(\n        source_statement_claim_id,\n        evidence_id\n    );\n\nCREATE INDEX semantic_candidate_review_events_candidate_time_idx\n    ON semantic_candidate_review_events(\n        semantic_candidate_id,\n        reviewed_at,\n        id\n    );\n\nCREATE INDEX semantic_candidate_review_events_replacement_idx\n    ON semantic_candidate_review_events(replacement_candidate_id)\n    WHERE replacement_candidate_id IS NOT NULL;\n"
COMPLETE_DDL_SHA256 = "59f0ff868d229bf6bd029db272fedc39ead83e8153b63fd8d1a2e3925c00d6f2"
