EXPECTED_TABLE_NAMES_SHA256 = "48e3f7906043fb9d3bfb8b92d6df21f2daac14371ee0ee9d3faa5d9f2ca0aea9"
EXPECTED_INDEX_NAMES_SHA256 = "c309a49fd7fe02bb92bc3001a2ab74b3e0d93c38029fd7b21ba12fb01a29cddf"
RUNTIME_SCHEMA_DESIGN_SHA256 = "d13f146dfd6f394ebb660e420c09305a6daca6c0d34232713c9b91b21879310e"

def _canonical_sha256(value: object) -> str:
    data = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(data).hexdigest()

def runtime_schema_identity_payload() -> dict[str, object]:
    return {
        "complete_ddl_sha256": COMPLETE_DDL_SHA256,
        "expected_explicit_application_index_count": len(EXPECTED_INDEXES),
        "expected_explicit_application_index_names_sha256": EXPECTED_INDEX_NAMES_SHA256,
        "expected_user_table_count": len(EXPECTED_TABLES),
        "expected_user_table_names_sha256": EXPECTED_TABLE_NAMES_SHA256,
        "identity_contract_version": RUNTIME_SCHEMA_IDENTITY_CONTRACT_VERSION,
        "index_addendum_sha256": INDEX_ADDENDUM_SHA256,
        "initializer_policy_version": INITIALIZER_POLICY_VERSION,
        "schema_version": SCHEMA_VERSION,
    }

def compute_runtime_schema_design_sha256() -> str:
    return _canonical_sha256(runtime_schema_identity_payload())

if hashlib.sha256(COMPLETE_DDL.encode("utf-8")).hexdigest() != COMPLETE_DDL_SHA256:
    raise RuntimeError("Schema V5 COMPLETE_DDL identity mismatch")
if hashlib.sha256(INDEX_ADDENDUM.encode("utf-8")).hexdigest() != INDEX_ADDENDUM_SHA256:
    raise RuntimeError("Schema V5 INDEX_ADDENDUM identity mismatch")
if _canonical_sha256(list(EXPECTED_TABLES)) != EXPECTED_TABLE_NAMES_SHA256:
    raise RuntimeError("Schema V5 table-name identity mismatch")
if _canonical_sha256(list(EXPECTED_INDEXES)) != EXPECTED_INDEX_NAMES_SHA256:
    raise RuntimeError("Schema V5 index-name identity mismatch")
if compute_runtime_schema_design_sha256() != RUNTIME_SCHEMA_DESIGN_SHA256:
    raise RuntimeError("Schema V5 runtime identity mismatch")
